changeSet.sql:
CREATE TABLE story_likes (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    profile_id BIGINT NOT NULL,
    story_id   BIGINT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT STORY_LIKES_PROFILE_UQ UNIQUE (profile_id, story_id),
    CONSTRAINT STORY_LIKES_PROFILE_FK FOREIGN KEY (profile_id) REFERENCES profiles(id) ON DELETE CASCADE,
    CONSTRAINT STORY_LIKES_STORY_FK   FOREIGN KEY (story_id)   REFERENCES stories(id)  ON DELETE CASCADE
);

CREATE INDEX idx_story_likes_profile ON story_likes(profile_id);
CREATE INDEX idx_story_likes_story   ON story_likes(story_id);
